#!/usr/bin/env bash
# ============================================================================
# ZONO 10.2B — live runtime acceptance fixes (3 Hebrew UI leaks + repo migration)
# NOTE: the P1 DB fix (properties.formatted_address) is ALREADY APPLIED to production.
# This patch is the 3 code fixes (Hebrew label leaks) + the migration file for repo truth.
# Run from the repo root (/Users/talzatelman/code/zono-os):
#   bash apply-zono-10-2b.sh
# ============================================================================
set -euo pipefail
if [ ! -d .git ]; then echo "ERROR: run this from the zono-os repo root." >&2; exit 1; fi
echo "→ Syncing with origin/main…"
git fetch origin main
git checkout main
git pull --ff-only origin main || true
PATCH="$(mktemp /tmp/zono-10-2b.XXXXXX.patch)"
base64 -d > "$PATCH" <<'PATCH_B64'

PATCH_B64
echo "→ Applying 10.2B commit…"
git am --3way "$PATCH" || { echo "git am failed — resolve, then 'git am --continue'." >&2; exit 1; }
echo "→ Pushing to origin/main…"
git push origin main
rm -f "$PATCH"
echo "✓ ZONO 10.2B applied and pushed. Vercel will deploy the 3 UI-leak fixes."
